const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let checked={};try{checked=JSON.parse(localStorage.getItem('interviewStudyProgress')||'{}')||{}}catch{}
const nav=document.getElementById('navigation');let group='';
nav.innerHTML=sections.map((s,i)=>{let h='';if(group!==s.group){group=s.group;h=`<div class="navGroup">${escapeHtml(group)}</div>`}return h+`<a href="#${s.id}"><span>${String(i+1).padStart(2,'0')}</span>${escapeHtml(s.title)}</a>`}).join('');
document.getElementById('sections').innerHTML=sections.map((s,i)=>`<article class="resumeCard" id="${s.id}"><div class="cardHeader"><span class="sectionNumber">${String(i+1).padStart(2,'0')}</span><div class="cardTitle"><div class="category">${s.group}</div><h2>${escapeHtml(s.title)}</h2><div class="meta">${escapeHtml(s.meta)}</div></div></div><div class="resumeText">${['general','summary','skills','education'].includes(s.id)?s.resume.map(t=>`<p>${escapeHtml(t)}</p>`).join(''):`<ul>${s.resume.map(t=>`<li>${escapeHtml(t)}</li>`).join('')}</ul>`}</div><details class="topics"><summary><span class="symbol">◎</span> Key technology & topics <span class="count">${s.topics.length} topics</span></summary><div class="panel">${s.topics.map(([t,p])=>`<div class="topic"><h3>${escapeHtml(t)}</h3><p>${escapeHtml(p)}</p></div>`).join('')}</div></details><details class="questions"><summary><span class="symbol">↗</span> Interview questions <span class="count">${s.questions.length} prompts</span><span class="progressLabel" data-progress="${s.id}"></span></summary><div class="panel">${s.questions.map((q,j)=>`<label class="question"><input type="checkbox" data-key="${s.id}-${j}" ${checked[s.id+'-'+j]?'checked':''} aria-label="Practiced: ${escapeHtml(q)}"><span>${escapeHtml(q)}</span></label>`).join('')}<div class="focus"><strong>Bring to the conversation</strong>${escapeHtml(s.focus)}</div></div></details><div class="progressTrack"><div class="progressFill" data-fill="${s.id}"></div></div></article>`).join('');
const total=sections.reduce((a,s)=>a+s.questions.length,0);document.getElementById('sectionCount').textContent=sections.length;document.getElementById('questionCount').textContent=total;
function updateProgress(){let done=0;sections.forEach(s=>{const n=s.questions.filter((_,j)=>checked[s.id+'-'+j]).length;done+=n;document.querySelector(`[data-progress="${s.id}"]`).textContent=`${n} / ${s.questions.length} practiced`;document.querySelector(`[data-fill="${s.id}"]`).style.width=`${n/s.questions.length*100}%`});document.getElementById('progressCount').textContent=done}updateProgress();
document.addEventListener('change',e=>{if(!e.target.matches('[data-key]'))return;checked[e.target.dataset.key]=e.target.checked;try{localStorage.setItem('interviewStudyProgress',JSON.stringify(checked))}catch{}updateProgress()});
document.getElementById('expand').onclick=()=>document.querySelectorAll('.resumeCard:not([hidden]) details').forEach(d=>d.open=true);
document.getElementById('collapse').onclick=()=>document.querySelectorAll('details').forEach(d=>d.open=false);
document.getElementById('search').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();let count=0;sections.forEach(s=>{const card=document.getElementById(s.id);const match=JSON.stringify(s).toLowerCase().includes(q);card.hidden=!match;if(match)count++;if(q&&match)card.querySelectorAll('details').forEach(d=>d.open=true)});document.getElementById('empty').hidden=count>0});
nav.addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;const card=document.querySelector(a.getAttribute('href'));if(card.hidden){document.getElementById('search').value='';document.getElementById('search').dispatchEvent(new Event('input'))}});
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){nav.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}}),{rootMargin:'-5% 0px -65% 0px'});document.querySelectorAll('.resumeCard').forEach(c=>observer.observe(c));
let printState=[];window.addEventListener('beforeprint',()=>{printState=[...document.querySelectorAll('details')].map(d=>d.open);document.querySelectorAll('details').forEach(d=>d.open=true)});window.addEventListener('afterprint',()=>document.querySelectorAll('details').forEach((d,i)=>d.open=printState[i]));document.getElementById('print').onclick=()=>window.print();
